mapper.insert:
/* 메뉴관리: 메뉴 저장 쿼리 (insertMenu)*/


		update ocuoc_menun_m
		set MENU_NM			= #{menuNm}
		, MENU_LEVEL		= '2'
		, UPRN_MENU_ID		= #{uprnMenuId}
		, MENU_SER			= #{menuSer}
		, MENU_URL			= #{menuUrl}
		, USE_YN			= #{useYn}
		, LAST_CHNG_EMPNO	= #{lastChngEmpno}
		, LAST_CHNG_DTTM	= TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24MISS')
		where MENU_ID = #{menuId}



		INSERT INTO ocuoc_menun_m
		(
		  MENU_ID
		, MENU_NM
		, MENU_LEVEL
		, UPRN_MENU_ID
		, MENU_SER
		, MENU_URL
		, USE_YN
		, LAST_CHNG_EMPNO
		, LAST_CHNG_DTTM
		, FRST_REG_EMPNO
		, FRST_REG_DTTM
		)
		VALUES
		(
		(select 'MENU'||LPAD(NVL(MAX(TO_NUMBER(SUBSTR(MENU_ID, 5))),TO_NUMBER(SUBSTR(#{uprnMenuId},5)))+1,4,'0')
		   from ocuoc_menun_m	-- 메뉴관리
		  where UPRN_MENU_ID = #{uprnMenuId})
		, #{menuNm}
		, '2'
		, #{uprnMenuId}
		, #{menuSer}
		, #{menuUrl}
		, #{useYn}
		, #{lastChngEmpno}
		, TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24MISS')
		, #{lastChngEmpno}
		, TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24MISS')
		)

mapper.delete:
/* 메뉴관리: 메뉴 삭제 쿼리 (deleteMenu)*/
DELETE
FROM ocuoc_menun_m
WHERE MENU_ID = #{menuId}

mapper.insert:
/* 메뉴관리: 버튼 저장 쿼리 (insertBtnList)*/
MERGE INTO ocuoc_buttn_m T
USING (
    SELECT
        #{menuId} AS MENU_ID,
        #{btnSeq} AS BTN_SEQ,
		#{areaCd} AS AREA_CD
    FROM DUAL
	)S
    ON (
        T.MENU_ID = S.MENU_ID
        AND T.BTN_SEQ = S.BTN_SEQ
		AND T.AREA_CD = S.AREA_CD
		)
    WHEN MATCHED THEN
    UPDATE SET
         T.USE_YN = #{useYn}
		,T.LAST_CHNG_EMPNO = #{lastChngEmpno}
		,T.LAST_CHNG_DTTM = TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24MISS')
    WHEN NOT MATCHED THEN
		INSERT(
				  MENU_ID
				, BTN_SEQ
				, BTN_CD
				, BTN_NM
				, AREA_CD
				, ACTION_CD
				, USE_YN
				, IOCN_URL
				, AUDIT_YN
				, LAST_CHNG_EMPNO
				, LAST_CHNG_DTTM
				, FRST_REG_EMPNO
				, FRST_REG_DTTM)
		VALUES ( #{menuId}
			   ,  (select nvl(max(t.btn_seq), 0) + 1
				   from (select btn_seq
						 from ocuoc_buttn_m
						 where menu_id = #{menuId}
						   and AREA_CD = #{areaCd}) t)
			   ,  #{btnCd}
			   ,  #{btnNm}
			   ,  #{areaCd}
			   ,  #{actionCd}
			   ,  #{useYn}
			   ,  #{iocnUrl}
			   ,  #{auditYn}
			   ,  #{lastChngEmpno}
			   ,  TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24MISS')
			   ,  #{lastChngEmpno}
			   ,  TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24MISS')
			   )

mapper.delete:
/* 메뉴관리: 버튼 삭제 쿼리 (deleteBtnList)*/
DELETE
FROM ocuoc_buttn_m
WHERE MENU_ID = #{menuId}
  AND BTN_SEQ = #{btnSeq}
  AND AREA_CD = #{areaCd}

/* 메뉴관리: 버튼 삭제시 권한도 삭제 쿼리 (deleteRoleBtn)*/
DELETE
FROM ocuoc_USBTN_m
WHERE MENU_ID = #{menuId}
  AND BTN_CD = #{btnCd}
